1	import Link from "next/link";
2	import type { Metadata } from "next";
3	import { MarketingHeader } from "@/components/marketing/MarketingHeader";
4	import { MarketingFooter } from "@/components/marketing/MarketingFooter";
5	import { Reveal } from "@/components/marketing/Reveal";
6	import { CtaBand } from "@/components/marketing/sections";
7	import {
8	  IconGame,
9	  IconGlobe,
10	  IconMail,
11	  IconShield,
12	  IconBackup,
13	  IconTerminal,
14	  IconGauge,
15	  IconApps,
16	  IconScale,
17	  IconServer,
18	  IconArrow,
19	} from "@/components/marketing/icons";
20	import { getPostsPage, iconForPost, formatDate, readMinutes, APP_URL } from "@/lib/blog";
21	
22	export const dynamic = "force-dynamic";
23	
24	const ICONS: Record<string, (p: { size?: number; className?: string }) => React.ReactElement> = {
25	  game: IconGame,
26	  globe: IconGlobe,
27	  mail: IconMail,
28	  shield: IconShield,
29	  backup: IconBackup,
30	  terminal: IconTerminal,
31	  gauge: IconGauge,
32	  apps: IconApps,
33	  scale: IconScale,
34	  server: IconServer,
35	};
36	
37	type Search = { q?: string; page?: string };
38	
39	function parsePage(v?: string): number {
40	  const n = Number.parseInt(v ?? "1", 10);
41	  return Number.isFinite(n) && n > 0 ? n : 1;
42	}
43	
44	/** Build a /blog URL preserving the search query and page number. */
45	function pageHref(page: number, q: string): string {
46	  const params = new URLSearchParams();
47	  if (q) params.set("q", q);
48	  if (page > 1) params.set("page", String(page));
49	  const qs = params.toString();
50	  return qs ? `/blog?${qs}` : "/blog";
51	}
52	
53	export async function generateMetadata({ searchParams }: { searchParams: Promise<Search> }): Promise<Metadata> {
54	  const { q, page: pageRaw } = await searchParams;
55	  const query = (q ?? "").trim();
56	  const page = parsePage(pageRaw);
57	  const suffix = page > 1 ? ` — page ${page}` : "";
58	  const title = `Blog — VPS & self-hosting guides${suffix}`;
59	  const description =
60	    "Practical guides on running a VPS: Minecraft and game servers, Linux security, pointing domains, and choosing the right hosting for your project.";
61	  // Per-page self-canonical. Search result listings are not canonical targets —
62	  // point them back at the clean index so thin/duplicate query pages don't index.
63	  const canonical = query ? "/blog" : pageHref(page, "");
64	  return {
65	    title,
66	    description,
67	    alternates: { canonical },
68	    ...(query ? { robots: { index: false, follow: true } } : {}),
69	    openGraph: {
70	      type: "website",
71	      title: `Nxeon Blog — VPS & self-hosting guides${suffix}`,
72	      description,
73	      url: `${APP_URL}${canonical}`,
74	    },
75	  };
76	}
77	
78	/** Cover for a card: real image if present, else a gradient + topic icon block. */
79	function CardCover({
80	  coverImage,
81	  iconName,
82	  className,
83	  iconSize = 30,
84	}: {
85	  coverImage: string | null;
86	  iconName: string;
87	  className: string;
88	  iconSize?: number;
89	}) {
90	  const Icon = ICONS[iconName] ?? IconServer;
91	  if (coverImage) {
92	    return (
93	      <div className={`overflow-hidden ${className}`}>
94	        {/* eslint-disable-next-line @next/next/no-img-element */}
95	        <img src={coverImage} alt="" loading="lazy" className="h-full w-full object-cover" />
96	      </div>
97	    );
98	  }
99	  return (
100	    <div className={`hero-aura flex items-center justify-center bg-navy-900 ${className}`}>
101	      <Icon size={iconSize} className="text-brand-300/70" />
102	    </div>
103	  );
104	}
105	
106	/** Compact, windowed numeric pager with prev/next. */
107	function Pager({ page, totalPages, q }: { page: number; totalPages: number; q: string }) {
108	  if (totalPages <= 1) return null;
109	  const window: number[] = [];
110	  const from = Math.max(1, page - 2);
111	  const to = Math.min(totalPages, page + 2);
112	  for (let i = from; i <= to; i++) window.push(i);
113	
114	  const linkCls =
115	    "inline-flex h-9 min-w-9 items-center justify-center gap-1.5 rounded-lg border border-white/10 bg-white/[0.04] px-3 text-sm font-medium text-slate-300 transition-colors hover:border-brand-400/50 hover:text-white";
116	  const disabledCls =
117	    "inline-flex h-9 min-w-9 items-center justify-center gap-1.5 rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 text-sm font-medium text-slate-600 cursor-not-allowed";
118	
119	  return (
120	    <nav className="mt-14 flex flex-wrap items-center justify-center gap-2" aria-label="Blog pagination">
121	      {page > 1 ? (
122	        <Link href={pageHref(page - 1, q)} rel="prev" className={linkCls} aria-label="Previous page">
123	          <IconArrow size={15} className="rotate-180" /> Prev
124	        </Link>
125	      ) : (
126	        <span className={disabledCls} aria-hidden>
127	          <IconArrow size={15} className="rotate-180" /> Prev
128	        </span>
129	      )}
130	
131	      {from > 1 && (
132	        <>
133	          <Link href={pageHref(1, q)} className={linkCls}>
134	            1
135	          </Link>
136	          {from > 2 && <span className="px-1 text-slate-600">…</span>}
137	        </>
138	      )}
139	
140	      {window.map((n) =>
141	        n === page ? (
142	          <span
143	            key={n}
144	            aria-current="page"
145	            className="inline-flex h-9 min-w-9 items-center justify-center rounded-lg border border-brand-500/50 bg-brand-500/15 px-3 text-sm font-semibold text-brand-200"
146	          >
147	            {n}
148	          </span>
149	        ) : (
150	          <Link key={n} href={pageHref(n, q)} className={linkCls}>
151	            {n}
152	          </Link>
153	        ),
154	      )}
155	
156	      {to < totalPages && (
157	        <>
158	          {to < totalPages - 1 && <span className="px-1 text-slate-600">…</span>}
159	          <Link href={pageHref(totalPages, q)} className={linkCls}>
160	            {totalPages}
161	          </Link>
162	        </>
163	      )}
164	
165	      {page < totalPages ? (
166	        <Link href={pageHref(page + 1, q)} rel="next" className={linkCls} aria-label="Next page">
167	          Next <IconArrow size={15} />
168	        </Link>
169	      ) : (
170	        <span className={disabledCls} aria-hidden>
171	          Next <IconArrow size={15} />
172	        </span>
173	      )}
174	    </nav>
175	  );
176	}
