178	export default async function BlogIndex({ searchParams }: { searchParams: Promise<Search> }) {
179	  const { q, page: pageRaw } = await searchParams;
180	  const query = (q ?? "").trim();
181	  const requestedPage = parsePage(pageRaw);
182	  const { posts, total, page, totalPages } = await getPostsPage({ page: requestedPage, q: query });
183	  const searching = query.length > 0;
184	
185	  // Feature the newest post only on page 1 of the default (non-search) view.
186	  const showFeatured = !searching && page === 1;
187	  const featured = showFeatured ? posts[0] : undefined;
188	  const grid = showFeatured ? posts.slice(1) : posts;
189	
190	  return (
191	    <div className="flex min-h-screen flex-col">
192	      {/* rel prev/next — hoisted into <head> by React 19. Google-legacy but still
193	          a positive crawl signal for a long paginated series. */}
194	      {page > 1 && <link rel="prev" href={`${APP_URL}${pageHref(page - 1, query)}`} />}
195	      {page < totalPages && <link rel="next" href={`${APP_URL}${pageHref(page + 1, query)}`} />}
196	
197	      <MarketingHeader />
198	      <main className="flex-1">
199	        {/* Hero */}
200	        <section className="relative overflow-hidden">
201	          <div
202	            className="pointer-events-none absolute inset-x-0 top-0 h-[380px] opacity-70"
203	            style={{ backgroundImage: "radial-gradient(ellipse 60% 50% at 50% 0%, rgba(111,71,245,0.16), transparent)" }}
204	          />
205	          <div className="relative mx-auto max-w-6xl px-5 py-20 text-center sm:px-6">
206	            <Reveal>
207	              <p className="section-label mb-3">The Nxeon Blog</p>
208	              <h1 className="text-4xl font-extrabold tracking-tight sm:text-5xl">
209	                Guides for people who <span className="grad-text">run their own servers</span>
210	              </h1>
211	              <p className="mx-auto mt-5 max-w-2xl text-lg text-slate-400">
212	                Straight-talking tutorials and comparisons on VPS hosting, game servers, Linux
213	                security, and domains — no fluff, just what actually works.
214	              </p>
215	
216	              {/* Search */}
217	              <form method="get" action="/blog" role="search" className="mx-auto mt-8 flex max-w-xl items-center gap-2">
218	                <div className="relative flex-1">
219	                  <svg
220	                    aria-hidden
221	                    viewBox="0 0 24 24"
222	                    fill="none"
223	                    className="pointer-events-none absolute left-3.5 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-500"
224	                  >
225	                    <circle cx="11" cy="11" r="7" stroke="currentColor" strokeWidth="2" />
226	                    <path d="m20 20-3-3" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
227	                  </svg>
228	                  <input
229	                    type="search"
230	                    name="q"
231	                    defaultValue={query}
232	                    placeholder="Search guides — e.g. minecraft, ssh, dns…"
233	                    aria-label="Search the blog"
234	                    className="w-full rounded-xl border border-white/10 bg-white/[0.04] py-3 pl-10 pr-4 text-sm text-white placeholder:text-slate-500 outline-none transition-colors focus:border-brand-400/60 focus:bg-white/[0.06]"
235	                  />
236	                </div>
237	                <button
238	                  type="submit"
239	                  className="rounded-xl border border-brand-500/40 bg-brand-500/15 px-5 py-3 text-sm font-semibold text-brand-200 transition-colors hover:bg-brand-500/25"
240	                >
241	                  Search
242	                </button>
243	              </form>
244	            </Reveal>
245	          </div>
246	        </section>
247	
248	        {/* Posts */}
249	        <section className="mx-auto max-w-6xl px-5 pb-24 sm:px-6">
250	          {searching && (
251	            <div className="mb-8 flex flex-wrap items-center justify-between gap-3">
252	              <p className="text-sm text-slate-400">
253	                {total === 0 ? "No results for" : `${total} result${total === 1 ? "" : "s"} for`}{" "}
254	                <span className="font-semibold text-white">“{query}”</span>
255	              </p>
256	              <Link href="/blog" className="inline-flex items-center gap-1.5 text-sm font-medium text-brand-300 hover:text-brand-200">
257	                Clear search
258	              </Link>
259	            </div>
260	          )}
261	
262	          {posts.length === 0 ? (
263	            <div className="card py-16 text-center">
264	              <p className="text-lg font-semibold text-white">
265	                {searching ? "Nothing matched your search" : "No posts yet"}
266	              </p>
267	              <p className="mt-2 text-sm text-slate-400">
268	                {searching ? (
269	                  <>
270	                    Try a broader term, or{" "}
271	                    <Link href="/blog" className="text-brand-300 hover:text-brand-200">
272	                      browse all guides
273	                    </Link>
274	                    .
275	                  </>
276	                ) : (
277	                  <>We&apos;re writing the first guides now — check back shortly.</>
278	                )}
279	              </p>
280	            </div>
281	          ) : (
282	            <>
283	              {/* Featured post — only on page 1 of the default view */}
284	              {featured && (
285	                <Reveal>
286	                  <Link
287	                    href={`/blog/${featured.slug}`}
288	                    className="card card-hover group flex flex-col gap-6 md:flex-row md:items-center"
289	                  >
290	                    <CardCover
291	                      coverImage={featured.coverImage}
292	                      iconName={iconForPost(featured)}
293	                      className="h-40 w-full shrink-0 rounded-2xl border border-white/[0.06] md:h-44 md:w-64"
294	                      iconSize={44}
295	                    />
296	                    <div className="min-w-0">
297	                      <div className="mb-3 flex flex-wrap items-center gap-2 text-xs text-slate-400">
298	                        <span className="rounded-full border border-brand-500/40 bg-brand-500/10 px-2.5 py-0.5 font-medium text-brand-300">
299	                          {featured.category}
300	                        </span>
301	                        <span>{formatDate(featured.publishedAt ?? featured.createdAt)}</span>
302	                        <span aria-hidden>·</span>
303	                        <span>{readMinutes(featured.body)} min read</span>
304	                      </div>
305	                      <h2 className="text-2xl font-bold tracking-tight text-white transition-colors group-hover:text-brand-200">
306	                        {featured.title}
307	                      </h2>
308	                      <p className="mt-2 line-clamp-3 text-slate-400">{featured.excerpt}</p>
309	                    </div>
310	                  </Link>
311	                </Reveal>
312	              )}
313	
314	              {grid.length > 0 && (
315	                <div className={`grid gap-5 sm:grid-cols-2 lg:grid-cols-3 ${featured ? "mt-6" : ""}`}>
316	                  {grid.map((post, i) => (
317	                    <Reveal key={post.id} delay={(i % 3) * 60}>
318	                      <Link
319	                        href={`/blog/${post.slug}`}
320	                        className="card card-hover group flex h-full flex-col overflow-hidden !p-0"
321	                      >
322	                        <CardCover
323	                          coverImage={post.coverImage}
324	                          iconName={iconForPost(post)}
325	                          className="aspect-[16/9] w-full border-b border-white/[0.06]"
326	                        />
327	                        <div className="flex flex-1 flex-col p-5">
328	                          <div className="mb-2 flex flex-wrap items-center gap-2 text-[11px] text-slate-500">
329	                            <span className="rounded-full border border-white/10 bg-white/[0.05] px-2 py-0.5 font-medium text-slate-300">
330	                              {post.category}
331	                            </span>
332	                            <span>{readMinutes(post.body)} min read</span>
333	                          </div>
334	                          <h3 className="text-base font-semibold text-white transition-colors group-hover:text-brand-200">
335	                            {post.title}
336	                          </h3>
337	                          <p className="mt-2 line-clamp-3 text-sm leading-relaxed text-slate-400">{post.excerpt}</p>
338	                          <span className="mt-4 inline-flex items-center gap-1.5 text-xs font-medium text-brand-300">
339	                            Read more <IconArrow size={13} />
340	                          </span>
341	                        </div>
342	                      </Link>
343	                    </Reveal>
344	                  ))}
345	                </div>
346	              )}
347	
348	              <Pager page={page} totalPages={totalPages} q={query} />
349	            </>
350	          )}
351	
352	          <div className="mt-20">
353	            <CtaBand />
354	          </div>
355	        </section>
356	      </main>
357	      <MarketingFooter />
358	    </div>
359	  );
360	}
