1	import type { Metadata } from "next";
2	import { notFound } from "next/navigation";
3	import { MarketingHeader } from "@/components/marketing/MarketingHeader";
4	import { MarketingFooter } from "@/components/marketing/MarketingFooter";
5	import { ArticleJsonLd, FaqJsonLd } from "@/components/marketing/StructuredData";
6	import { BlogPostView, type QuickFact, type RelatedItem } from "@/components/marketing/blogtemplate/BlogPostView";
7	import {
8	  getPublishedPost,
9	  getRelatedPosts,
10	  productLinkForPost,
11	  renderArticle,
12	  firstParagraph,
13	  accentForPost,
14	  iconForPost,
15	  authorInitials,
16	  formatDate,
17	  readMinutes,
18	  APP_URL,
19	} from "@/lib/blog";
20	
21	export const dynamic = "force-dynamic";
22	
23	type Params = { params: Promise<{ slug: string }> };
24	
25	export async function generateMetadata({ params }: Params): Promise<Metadata> {
26	  const { slug } = await params;
27	  const post = await getPublishedPost(slug);
28	  if (!post) return { title: "Post not found" };
29	
30	  const title = post.seoTitle || post.title;
31	  const description = post.seoDescription || post.excerpt || `${post.title} — a guide from the Nxeon blog.`;
32	  // Absolute cover URL for social cards, when the post has one.
33	  const ogImage = post.coverImage
34	    ? post.coverImage.startsWith("http")
35	      ? post.coverImage
36	      : `${APP_URL}${post.coverImage}`
37	    : undefined;
38	  return {
39	    title,
40	    description,
41	    alternates: { canonical: `/blog/${post.slug}` },
42	    openGraph: {
43	      type: "article",
44	      title,
45	      description,
46	      url: `${APP_URL}/blog/${post.slug}`,
47	      publishedTime: (post.publishedAt ?? post.createdAt).toISOString(),
48	      modifiedTime: post.updatedAt.toISOString(),
49	      authors: [post.author],
50	      tags: post.tags,
51	      ...(ogImage ? { images: [ogImage] } : {}),
52	    },
53	    twitter: { card: "summary_large_image", title, description, ...(ogImage ? { images: [ogImage] } : {}) },
54	  };
55	}
56	
57	export default async function BlogPostPage({ params }: Params) {
58	  const { slug } = await params;
59	  const post = await getPublishedPost(slug);
60	  if (!post) notFound();
61	
62	  const { html, toc, faq } = renderArticle(post.body);
63	  const published = post.publishedAt ?? post.createdAt;
64	  const relatedPosts = await getRelatedPosts(post, 3);
65	  const product = productLinkForPost(post);
66	  const mins = readMinutes(post.body);
67	
68	  // GEO "quick answer": a direct one-liner answer engines can lift, plus a few
69	  // genuinely useful facts pulled from the real post fields.
70	  const answer = (post.excerpt || firstParagraph(post.body)).trim();
71	  const facts: QuickFact[] = [
72	    { label: "Topic", value: post.category },
73	    { label: "Read time", value: `${mins} min read` },
74	    ...(post.tags.length ? [{ label: "Covers", value: post.tags.slice(0, 3).join(", ") }] : []),
75	    { label: "Last updated", value: formatDate(post.updatedAt) },
76	  ].slice(0, 4);
77	  const quickAnswer = answer ? { answer, facts } : null;
78	
79	  // Only surface an "Updated" pill when the post was genuinely revised after
80	  // publishing (more than a day later).
81	  const updatedLabel =
82	    post.updatedAt.getTime() - published.getTime() > 24 * 60 * 60 * 1000
83	      ? `Updated ${formatDate(post.updatedAt)}`
84	      : null;
85	
86	  const related: RelatedItem[] = relatedPosts.map((r) => ({
87	    slug: r.slug,
88	    title: r.title,
89	    category: r.category,
90	    readMins: readMinutes(r.body),
91	    coverImage: r.coverImage,
92	    iconName: iconForPost(r),
93	  }));
94	
95	  return (
96	    <div className="flex min-h-screen flex-col">
97	      <MarketingHeader />
98	      <main className="flex-1">
99	        <ArticleJsonLd
100	          title={post.seoTitle || post.title}
101	          description={post.seoDescription || post.excerpt}
102	          slug={post.slug}
103	          published={published.toISOString()}
104	          updated={post.updatedAt.toISOString()}
105	          author={post.author}
106	          image={post.coverImage}
107	        />
108	        {faq.length > 0 && <FaqJsonLd items={faq} />}
109	
110	        <BlogPostView
111	          title={post.title}
112	          deck={post.excerpt}
113	          category={post.category}
114	          author={post.author}
115	          authorInitials={authorInitials(post.author)}
116	          dateLabel={formatDate(published)}
117	          updatedLabel={updatedLabel}
118	          readingLabel={`${mins} min read`}
119	          accent={accentForPost(post)}
120	          coverImage={post.coverImage}
121	          iconName={iconForPost(post)}
122	          tags={post.tags}
123	          contentHtml={html}
124	          toc={toc}
125	          quickAnswer={quickAnswer}
126	          product={product}
127	          related={related}
128	        />
129	      </main>
130	      <MarketingFooter />
131	    </div>
132	  );
133	}
