618	/** Icon name (see components/marketing/icons) that best fits a post's topic. */
619	export function iconForPost(post: Pick<BlogPost, "category" | "tags" | "title">): string {
620	  const hay = `${post.category} ${post.tags.join(" ")} ${post.title}`.toLowerCase();
621	  const has = (...ks: string[]) => ks.some((k) => hay.includes(k));
622	  if (has("minecraft", "rust", "game", "valheim", "palworld", "ark", "server hosting", "modpack")) return "game";
623	  if (has("dns", "domain", "nameserver", "whois", "record")) return "globe";
624	  if (has("email", "mail", "smtp", "spf", "dkim", "imap")) return "mail";
625	  if (has("security", "firewall", "ssh", "ssl", "vpn", "hardening", "fail2ban", "port")) return "shield";
626	  if (has("backup", "snapshot", "restore")) return "backup";
627	  if (has("docker", "linux", "terminal", "command", "cli", "systemd", "bash")) return "terminal";
628	  if (has("performance", "monitor", "ram", "cpu", "benchmark", "speed", "tune")) return "gauge";
629	  if (has("web hosting", "wordpress", "website", "php", "nginx")) return "apps";
630	  if (has("price", "pricing", "cost", "cheap", "compare", "vs", "plan")) return "scale";
631	  return "server";
632	}
