85	/* ── reading progress (0→1) across the article body ──────────────────────── */
86	function useReadingProgress<T extends HTMLElement>() {
87	  const ref = useRef<T | null>(null);
88	  const [p, setP] = useState(0);
89	  useEffect(() => {
90	    const el = ref.current;
91	    if (!el) return;
92	    let raf = 0;
93	    const compute = () => {
94	      raf = 0;
95	      const r = el.getBoundingClientRect();
96	      const vh = window.innerHeight || 1;
97	      const total = r.height - vh;
98	      const travelled = -r.top;
99	      setP(total <= 0 ? 1 : Math.max(0, Math.min(1, travelled / total)));
100	    };
101	    const onScroll = () => {
102	      if (!raf) raf = requestAnimationFrame(compute);
103	    };
104	    compute();
105	    window.addEventListener("scroll", onScroll, { passive: true });
106	    window.addEventListener("resize", onScroll, { passive: true });
107	    return () => {
108	      window.removeEventListener("scroll", onScroll);
109	      window.removeEventListener("resize", onScroll);
110	      if (raf) cancelAnimationFrame(raf);
111	    };
112	  }, []);
113	  return { ref, p };
114	}
