116	/* ── scroll-spy: which section id is currently in view ───────────────────── */
117	function useScrollSpy(ids: string[]) {
118	  const [active, setActive] = useState(ids[0] ?? "");
119	  useEffect(() => {
120	    if (typeof IntersectionObserver === "undefined" || ids.length === 0) return;
121	    const seen = new Map<string, number>();
122	    const io = new IntersectionObserver(
123	      (entries) => {
124	        for (const e of entries) seen.set(e.target.id, e.intersectionRatio);
125	        let best = "";
126	        let bestRatio = -1;
127	        for (const [id, ratio] of seen) {
128	          if (ratio > bestRatio) {
129	            best = id;
130	            bestRatio = ratio;
131	          }
132	        }
133	        if (best && bestRatio > 0) setActive(best);
134	      },
135	      { rootMargin: "-20% 0px -55% 0px", threshold: [0, 0.25, 0.5, 1] },
136	    );
137	    for (const id of ids) {
138	      const el = document.getElementById(id);
139	      if (el) io.observe(el);
140	    }
141	    return () => io.disconnect();
142	  }, [ids]);
143	  return active;
144	}
