"use client";

import Link from "next/link";
import { useEffect, useState } from "react";

/**
 * Sticky conversion CTA — fades in after the visitor scrolls past the hero so the
 * primary action is always one click away on a long page (CRO: repeat the CTA at
 * every decision depth). Dismissible. Hidden until scrolled, and after dismiss.
 */
export function StickyCTA() {
  const [show, setShow] = useState(false);
  const [dismissed, setDismissed] = useState(false);

  useEffect(() => {
    const onScroll = () => setShow(window.scrollY > 900);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  if (dismissed) return null;
  return (
    <div className={`fixed inset-x-0 bottom-0 z-40 flex justify-center px-4 pb-4 transition-all duration-300 ${show ? "translate-y-0 opacity-100" : "pointer-events-none translate-y-6 opacity-0"}`}>
      <div className="glass flex items-center gap-3 rounded-full border-white/10 px-3 py-2 pl-5 shadow-2xl glow-brand">
        <span className="hidden text-sm text-slate-300 sm:inline">Your server is <span className="font-semibold text-white">47 seconds</span> away.</span>
        <Link href="/register" className="btn-primary whitespace-nowrap px-5 py-2 text-sm">Deploy my server →</Link>
        <button onClick={() => setDismissed(true)} aria-label="Dismiss" className="flex h-7 w-7 items-center justify-center rounded-full text-slate-500 hover:bg-white/10 hover:text-white">✕</button>
      </div>
    </div>

