import { chromium } from "/opt/nxeon/node_modules/playwright/index.mjs";
import { writeFileSync } from "node:fs";

const URLS = [
  "https://nxeon.cloud/blog",
  "https://nxeon.cloud/blog/how-to-install-cs2-plugins-metamod-counterstrikesharp",
  "https://nxeon.cloud/blog/subnetting-made-simple-cidr-netmasks-and-host-counts",
];
const BLOCK_HOSTS = /facebook\.net|facebook\.com|google-analytics\.com|googletagmanager\.com|doubleclick\.net|clarity\.ms|hotjar|googleadservices|google\.com\/ccm|googlesyndication/;

const browser = await chromium.launch({ headless: true });
const context = await browser.newContext({
  viewport: { width: 390, height: 844 },
  deviceScaleFactor: 2,
  isMobile: true,
  hasTouch: true,
  userAgent:
    "Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1 NxeonAudit",
});
const blocked = [];
await context.route("**/*", (r) => {
  const req = r.request();
  if (req.method() !== "GET" || BLOCK_HOSTS.test(req.url())) {
    blocked.push(`${req.method()} ${req.url().slice(0, 120)}`);
    return r.abort();
  }
  return r.continue();
});
// Neutralise sendBeacon before any page script runs.
await context.addInitScript(() => {
  try { navigator.sendBeacon = () => true; } catch {}
});

const results = [];
for (const url of URLS) {
  const page = await context.newPage();
  const consoleErrors = [];
  const reqs = [];
  page.on("console", (m) => { if (m.type() === "error") consoleErrors.push(m.text().slice(0, 200)); });
  page.on("pageerror", (e) => consoleErrors.push("pageerror: " + String(e).slice(0, 200)));
  page.on("requestfinished", async (req) => {
    try {
      const res = await req.response();
      const sizes = await req.sizes();
      reqs.push({ url: req.url().slice(0, 110), type: req.resourceType(), status: res?.status(), bytes: sizes.responseBodySize });
    } catch {}
  });
  const t0 = Date.now();
  await page.goto(url, { waitUntil: "load", timeout: 45000 });
  await page.waitForTimeout(2500);
  const loadMs = Date.now() - t0;
  const m = await page.evaluate(() => {
    const iw = window.innerWidth;
    const se = document.scrollingElement;
    const clippedByAncestor = (el) => {
      let p = el.parentElement;
      while (p && p !== document.body) {
        const cs = getComputedStyle(p);
        if (/(auto|scroll|hidden|clip)/.test(cs.overflowX)) {
          const r = p.getBoundingClientRect();
          if (r.right <= iw + 1) return true;
        }
        p = p.parentElement;
      }
      return false;
    };
    const offenders = [];
    for (const el of document.querySelectorAll("body *")) {
      const r = el.getBoundingClientRect();
      if (r.width === 0 || r.height === 0) continue;
      if (r.right > iw + 1 || r.left < -1) {
        const cs = getComputedStyle(el);
        if (cs.position === "fixed") continue;
        if (clippedByAncestor(el)) continue;
        offenders.push({
          tag: el.tagName.toLowerCase(),
          cls: (el.getAttribute("class") || "").slice(0, 90),
          w: Math.round(r.width),
          right: Math.round(r.right),
          text: (el.textContent || "").trim().slice(0, 70),
        });
      }
    }
    offenders.sort((a, b) => b.right - a.right);
    // First CTA to a money page within <main>
    const moneyRe = /^\/(vps|game-servers|web-hosting|domains|business-email|minecraft-server-hosting|free-minecraft|pricing|register|[a-z0-9-]+-server-hosting)(\?|$)/;
    const main = document.querySelector("main") || document.body;
    const links = [...main.querySelectorAll("a[href]")].filter((a) => {
      const h = a.getAttribute("href");
      const r = a.getBoundingClientRect();
      return moneyRe.test(h) && r.width > 0 && r.height > 0 && getComputedStyle(a).visibility !== "hidden";
    });
    const firstCta = links[0]
      ? { href: links[0].getAttribute("href"), text: links[0].textContent.trim().slice(0, 50), top: Math.round(links[0].getBoundingClientRect().top + window.scrollY) }
      : null;
    const header = document.querySelector("main header");
    const imgs = [...document.querySelectorAll("main img")].map((i) => ({
      src: i.getAttribute("src")?.slice(0, 70),
      attrW: i.getAttribute("width"),
      attrH: i.getAttribute("height"),
      natural: `${i.naturalWidth}x${i.naturalHeight}`,
      rendered: `${Math.round(i.getBoundingClientRect().width)}x${Math.round(i.getBoundingClientRect().height)}`,
      loading: i.getAttribute("loading"),
    }));
    const pres = [...document.querySelectorAll("main pre")].map((p) => ({ sw: p.scrollWidth, cw: p.clientWidth }));
    return {
      innerWidth: iw,
      scrollWidth: se.scrollWidth,
      docHeight: se.scrollHeight,
      heroHeight: header ? Math.round(header.getBoundingClientRect().height) : null,
      offenders: offenders.slice(0, 12),
      offenderCount: offenders.length,
      firstCta,
      moneyLinkCount: links.length,
      imgs: imgs.slice(0, 12),
      pres,
      h1: document.querySelector("h1")?.textContent?.trim().slice(0, 80),
    };
  });
  const byType = {};
  let total = 0;
  for (const r of reqs) { byType[r.type] = (byType[r.type] || 0) + (r.bytes || 0); total += r.bytes || 0; }
  const bigReqs = reqs.filter((r) => (r.bytes || 0) > 150000).map((r) => `${r.type} ${r.bytes} ${r.url}`);
  const bad = reqs.filter((r) => r.status && r.status >= 400).map((r) => `${r.status} ${r.url}`);
  results.push({ url, loadMs, consoleErrors, reqCount: reqs.length, totalBytes: total, byType, bigReqs, badReqs: bad, ...m });
  await page.close();
}
await browser.close();
writeFileSync(new URL("./mobile_results.json", import.meta.url), JSON.stringify({ results, blocked }, null, 2));
console.log(JSON.stringify({ results, blockedCount: blocked.length, blockedSample: blocked.slice(0, 10) }, null, 2));

